import React, { useState, useEffect } from "react";
import { toast } from "react-toastify";
import "react-toastify/dist/ReactToastify.css";
import "./UserManagement.css";
import { Search } from "lucide-react";
import {
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Button,
  MenuItem,
  Select,
  CircularProgress,
  FormControl,
  InputLabel,
} from "@mui/material";
import { useDispatch, useSelector } from "react-redux";
import { selectAuthToken } from "../../redux/features/Auth/AuthSelectors";
import {
  selectUsers,
  selectRoles,
  selectRoleComponents,
  selectUserRoles,
  selectLoading,
  selectComponentsLoading,
  selectUserRolesLoading,
  selectActionsLoading,
} from "../../redux/features/UserManagement/UserManagementSelectors";
import {
  fetchUsers,
  fetchRoles,
  fetchRoleComponents,
  addRole,
  deleteRole,
  submitRoleComponents,
  getUserPermission,
  assignUserRole,
  removeRoleFromUser as removeRoleFromUserThunk,
} from "../../redux/features/UserManagement/UserManagementThunks";
import { clearUserRoles } from "../../redux/features/UserManagement/UserManagementSlice";
import {
  RolesSkeleton,
  UsersSkeleton,
  UserRolesSkeleton,
  ComponentsSkeleton,
} from "./UserManagementSkeleton";

const componentCategories = {
  Dashboard: {
    vCenter: ["Overview", "Hosts", "Data Stores", "VMS"],
    Proxmox: ["PX-Overview", "PX-Nodes", "PX-Storage", "PX-VMs"],
    IPMI: ["IpmiDashboard"],
    HyperV: ["HyperV"],
  },
  Reports: ["Template", "Generate Reports"],
  Schedule: ["Schedule"],
  Pools: ["Pools"],
  IpPools: ["IpPools"],
  Tasks: ["Tasks"],
  Settings: [
    "TOTP",
    "Domain",
    "IPMI",
    "Cluster",
    "SSL",
    "SMTP",
    "RBAC",
    "Retention Period",
  ],
};
const UserManagement = () => {
  const dispatch = useDispatch();
  const users = useSelector(selectUsers);
  const roles = useSelector(selectRoles);
  const roleComponents = useSelector(selectRoleComponents);
  const userRoles = useSelector(selectUserRoles);
  const loading = useSelector(selectLoading);
  const isComponentsLoading = useSelector(selectComponentsLoading);
  const userRolesLoading = useSelector(selectUserRolesLoading);
  const actionsLoading = useSelector(selectActionsLoading);
  const [activeTab, setActiveTab] = useState("roles");
  const [searchTerm, setSearchTerm] = useState("");
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);
  const [role, setRole] = useState("");
  const [components, setComponents] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [showRoleDialog, setShowRoleDialog] = useState(false);
  const [selectedRole, setSelectedRole] = useState("");
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [selectedSubCategory, setSelectedSubCategory] = useState(null);
  const flattenAllComponents = () => {
    return Object.values(componentCategories).flatMap((cat) => {
      if (Array.isArray(cat)) return cat;
      if (typeof cat === "object" && cat !== null) {
        return Object.values(cat).flat();
      }
      return [];
    });
  };

  const token = useSelector(selectAuthToken);

  useEffect(() => {
    dispatch(fetchUsers({ token, first: 0, limit: itemsPerPage }));
    dispatch(fetchRoles({ token }));
  }, [dispatch, token]);

  useEffect(() => {
    setComponents(roleComponents || []);
  }, [roleComponents]);

  useEffect(() => {
    setFilteredUsers(users || []);
  }, [users]);

  useEffect(() => {
    if (selectedUser) {
      dispatch(getUserPermission({ token, username: selectedUser }));
    } else {
      dispatch(clearUserRoles());
      setRole("");
      setComponents([]);
    }
  }, [selectedUser, dispatch, token]);

  const showError = (message) => toast.error(message);
  const showSuccess = (message) => toast.success(message);

  const handleSearch = (term) => {
    setSearchTerm(term);
    setCurrentPage(1);

    if (term.trim() === "") {
      dispatch(
        fetchUsers({
          token,
          search: "",
          first: 0,
          limit: itemsPerPage,
        }),
      );
    }
  };

  const handleSearchKeyDown = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleSearchClick();
    }
  };

  const handleSearchClick = () => {
    setCurrentPage(1);
    dispatch(
      fetchUsers({
        token,
        search: searchTerm,
        first: 0,
        limit: itemsPerPage,
      }),
    );
  };

  const handlePageSizeChange = (value) => {
    const parsedSize = parseInt(value, 10);
    if (!parsedSize || parsedSize < 1) return;
    setItemsPerPage(parsedSize);
    setCurrentPage(1);
    dispatch(fetchUsers({ token, search: searchTerm, first: 0, limit: parsedSize }));
  };

  const handlePageChange = (newPage) => {
    if (newPage < 1) return;
    setCurrentPage(newPage);
    const first = (newPage - 1) * itemsPerPage;
    const limit = itemsPerPage;
    dispatch(fetchUsers({ token, search: searchTerm, first, limit }));
  };

  const handleUserClick = async (username) => {
    const newSelected = selectedUser === username ? null : username;
    setSelectedUser(newSelected);
  };
  const loadRoleComponents = async (selectedRole) => {
    dispatch(fetchRoleComponents({ token, role: selectedRole }));
  };
  const handleRoleSelect = (selectedRole) => {
    if (role === selectedRole) {
      setRole("");
      setComponents([]);
      setSelectedCategory(null);
      setSelectedSubCategory(null);
      return;
    }
    setRole(selectedRole);
    setSelectedCategory(null);
    setSelectedSubCategory(null);
    loadRoleComponents(selectedRole);
  };
  const handleCategorySelect = (category) => {
    setSelectedCategory(category === selectedCategory ? null : category);
    setSelectedSubCategory(null);
  };

  const handleSubCategorySelect = (subcat) => {
    setSelectedSubCategory(subcat === selectedSubCategory ? null : subcat);
  };
  const handleComponentChange = (component) => {
    setComponents((prev) => {
      if (prev.includes(component)) {
        return prev.filter((c) => c !== component);
      }
      if (role) {
        return [...prev, component];
      }
      return prev;
    });
  };

  const getVisibleComponents = () => {
    if (!selectedCategory) return flattenAllComponents();
    const categoryData = componentCategories[selectedCategory];
    if (Array.isArray(categoryData)) return categoryData;
    if (selectedSubCategory) return categoryData[selectedSubCategory] || [];
    return [];
  };

  const handleToggleAll = () => {
    const visible = getVisibleComponents();
    if (visible.length === 0 || !role) return;

    const areAllSelected = visible.every((comp) => components.includes(comp));

    if (areAllSelected) {
      setComponents((prev) => prev.filter((comp) => !visible.includes(comp)));
    } else {
      setComponents((prev) => {
        const newComponents = [...prev];
        visible.forEach((comp) => {
          if (!newComponents.includes(comp)) {
            newComponents.push(comp);
          }
        });
        return newComponents;
      });
    }
  };

  const handleAddRole = async () => {
    if (!role.trim()) {
      showError("Please enter a role name");
      return;
    }
    try {
      const res = await dispatch(addRole({ token, role })).unwrap();
      const code = res?.data?.code;
      // In this API, 'msg' is often generic while 'data' contains the specific error detail
      const message =
        res?.data?.data && typeof res?.data?.data === "string"
          ? res.data.data
          : res?.data?.msg || "Failed to add role";

      if ([20, 200, 201].includes(code)) {
        showSuccess(res?.data?.msg || "Role created successfully");
        dispatch(fetchRoles({ token }));
        setRole("");
      } else if (code === 400) {
        showError(message || "Role already exists");
      } else {
        showError(message || "Failed to add role");
      }
    } catch (err) {
      showError(err || "Failed to add role");
    }
  };

  const handleDelete = async (roleToDelete) => {
    try {
      const res = await dispatch(
        deleteRole({ token, role: roleToDelete }),
      ).unwrap();
      const code = res?.data?.code || res?.status;
      const message = res?.data?.msg || res?.data?.data;

      if ([200, 204].includes(code)) {
        showSuccess(message || "Role deleted successfully!");
      } else {
        showError(message || "Failed to delete role");
      }
    } catch (err) {
      const errorMsg =
        typeof err === "string"
          ? err
          : err?.msg || err?.message || "Failed to delete role";
      showError(errorMsg);
    }
  };

  const handleSubmit = async () => {
    if (!role) {
      showError("Please select a role");
      return;
    }
    try {
      const res = await dispatch(
        submitRoleComponents({ token, role, components }),
      ).unwrap();
      const code = res?.data?.code || res?.status;
      const message = res?.data?.msg || res?.data?.data;

      if (code === 200) {
        showSuccess(message || "Role and components saved successfully");
        dispatch(fetchRoles({ token }));
        setComponents([]);
        setRole("");
        setSelectedCategory(null);
        setSelectedSubCategory(null);
      } else {
        showError(message || "Failed to save role and components");
      }
    } catch (err) {
      const errorMsg =
        typeof err === "string"
          ? err
          : err?.msg || err?.message || "Failed to save role and components";
      showError(errorMsg);
    }
  };
  const handleRoleAssignment = async () => {
    if (!selectedRole) {
      showError("Please select a role");
      return;
    }
    if (!selectedUser) {
      showError("Please select a user");
      return;
    }
    try {
      const res = await dispatch(
        assignUserRole({ token, username: selectedUser, role: selectedRole }),
      ).unwrap();
      const code = res?.data?.code || res?.status;
      const message = res?.data?.msg || res?.data?.data;

      if (code === 200) {
        showSuccess(message || "Role assigned successfully");
        setShowRoleDialog(false);
        setSelectedRole("");
      } else {
        showError(message || "Failed to assign role");
      }
    } catch (err) {
      const errorMsg =
        typeof err === "string"
          ? err
          : err?.msg || err?.message || "Failed to assign role";
      showError(errorMsg);
    }
  };

  const handleAssignRole = () => {
    if (!selectedUser) {
      showError("Please select a user first");
      return;
    }
    setShowRoleDialog(true);
  };

  const removeRoleFromUser = async (username, roleToRemove) => {
    try {
      const res = await dispatch(
        removeRoleFromUserThunk({ token, username, role: roleToRemove }),
      ).unwrap();
      const code = res?.data?.code || res?.status;
      const message = res?.data?.msg || res?.data?.data;

      if ([200, 204].includes(code)) {
        showSuccess(message || "Role removed successfully");
        dispatch(getUserPermission({ token, username }));
      } else {
        showError(message || "Failed to remove role");
      }
    } catch (err) {
      const errorMsg =
        typeof err === "string"
          ? err
          : err?.msg || err?.message || "Failed to remove role";
      showError(errorMsg);
    }
  };
  const renderComponentsPanel = () => {
    const visible = getVisibleComponents();
    const isListMode = !(
      !selectedCategory === false &&
      !selectedSubCategory &&
      typeof componentCategories[selectedCategory] === "object" &&
      !Array.isArray(componentCategories[selectedCategory])
    );

    // Determine if we should show the "Select All" checkbox
    // True if we are showing a list of components (not subcategory buttons)
    const showSelectAll = visible.length > 0;
    const areAllVisibleSelected =
      showSelectAll && visible.every((c) => components.includes(c));

    if (!selectedCategory) {
      return (
        <>
          {showSelectAll && (
            <div className="flex items-center gap-5 p-2 bg-gray-50/50 sticky top-0 z-10 border-b mb-1">
              <input
                type="checkbox"
                id="select-all-components"
                checked={areAllVisibleSelected}
                onChange={handleToggleAll}
                className="rounded border-gray-300 text-[#1a365d] focus:ring-[#1a365d]/100"
                disabled={!role}
              />
              <label
                htmlFor="select-all-components"
                className="font-semibold text-[#1a365d] cursor-pointer"
              >
                Select All ({visible.length})
              </label>
            </div>
          )}
          {visible.map((component, idx) => (
            <div
              key={idx}
              className="flex items-center gap-5 hover:bg-gray-50 p-2 transition-colors duration-150 border-b last:border-none"
            >
              <input
                type="checkbox"
                id={`component-${idx}`}
                checked={components.includes(component)}
                onChange={() => handleComponentChange(component)}
                className="rounded border-gray-300 text-[#1a365d] focus:ring-[#1a365d]/100 mt-1"
                disabled={!role}
              />
              <label
                htmlFor={`component-${idx}`}
                className="select-none mt-1 cursor-pointer"
              >
                {component}
              </label>
            </div>
          ))}
        </>
      );
    }

    if (
      typeof componentCategories[selectedCategory] === "object" &&
      !Array.isArray(componentCategories[selectedCategory])
    ) {
      if (!selectedSubCategory) {
        return (
          <div className="flex flex-wrap gap-2 mb-4">
            {Object.keys(componentCategories[selectedCategory]).map(
              (subcat) => (
                <button
                  key={subcat}
                  onClick={() => handleSubCategorySelect(subcat)}
                  className={`px-3 py-1 rounded-md text-sm transition-all duration-200 ${selectedSubCategory === subcat
                    ? "bg-[#1a365d] text-white shadow-md shadow-[#1a365d]/20"
                    : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                    }`}
                >
                  {subcat}
                </button>
              ),
            )}
          </div>
        );
      }

      return (
        <>
          {showSelectAll && (
            <div className="flex items-center gap-5 p-2 bg-gray-50/50 sticky top-0 z-10 border-b mb-1">
              <input
                type="checkbox"
                id="select-all-subcomponents"
                checked={areAllVisibleSelected}
                onChange={handleToggleAll}
                className="rounded border-gray-300 text-[#1a365d] focus:ring-[#1a365d]/100"
                disabled={!role}
              />
              <label
                htmlFor="select-all-subcomponents"
                className="font-semibold text-[#1a365d] cursor-pointer"
              >
                Select All in {selectedSubCategory} ({visible.length})
              </label>
            </div>
          )}
          {visible.map((component, idx) => (
            <div
              key={idx}
              className="flex items-center gap-5 hover:bg-gray-50 p-2 transition-colors duration-150 border-b last:border-none"
            >
              <input
                type="checkbox"
                id={`component-${selectedSubCategory}-${idx}`}
                checked={components.includes(component)}
                onChange={() => handleComponentChange(component)}
                className="rounded border-gray-300 text-[#1a365d] focus:ring-[#1a365d]/100 mt-1"
                disabled={!role}
              />
              <label
                htmlFor={`component-${selectedSubCategory}-${idx}`}
                className="select-none mt-1 cursor-pointer"
              >
                {component}
              </label>
            </div>
          ))}
        </>
      );
    }

    if (Array.isArray(componentCategories[selectedCategory])) {
      return (
        <>
          {showSelectAll && (
            <div className="flex items-center gap-5 p-2 bg-gray-50/50 sticky top-0 z-10 border-b mb-1">
              <input
                type="checkbox"
                id="select-all-catcomponents"
                checked={areAllVisibleSelected}
                onChange={handleToggleAll}
                className="rounded border-gray-300 text-[#1a365d] focus:ring-[#1a365d]/100"
                disabled={!role}
              />
              <label
                htmlFor="select-all-catcomponents"
                className="font-semibold text-[#1a365d] cursor-pointer"
              >
                Select All in {selectedCategory} ({visible.length})
              </label>
            </div>
          )}
          {visible.map((component, idx) => (
            <div
              key={idx}
              className="flex items-center gap-5 hover:bg-gray-50 p-2 transition-colors duration-150 border-b last:border-none"
            >
              <input
                type="checkbox"
                id={`component-${selectedCategory}-${idx}`}
                checked={components.includes(component)}
                onChange={() => handleComponentChange(component)}
                className="rounded border-gray-300 text-[#1a365d] focus:ring-[#1a365d]/100 mt-1"
                disabled={!role}
              />
              <label
                htmlFor={`component-${selectedCategory}-${idx}`}
                className="select-none mt-1 cursor-pointer"
              >
                {component}
              </label>
            </div>
          ))}
        </>
      );
    }
    return null;
  };

  return (
    <div className="w-full md:w-[98%] h-auto md:h-[90vh] min-h-[75vh] mt-4 m-auto p-2 md:p-3 bg-white rounded-lg shadow-lg flex flex-col overflow-auto md:overflow-hidden">
      <div className="bg-white flex-1 p-4  overflow-y-auto rounded-md custom-scrollbar">
        <div className="flex justify-between items-center mb-6 w-full ">
          <div className="relative border-b mb-6 w-full">
            <div className="flex gap-6">
              <button
                className={`pb-3 px-6 font-semibold text-sm relative transition-all duration-300 ${activeTab === "roles"
                  ? "text-[#1a365d] after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-1 after:bg-[#1a365d] after:rounded after:transition-transform after:duration-500"
                  : "text-gray-600 hover:text-[#1a365d]"
                  }`}
                onClick={() => setActiveTab("roles")}
              >
                Role Management
              </button>
              <button
                className={`pb-3 px-6 font-semibold text-sm relative transition-all duration-300 ${activeTab === "users"
                  ? "text-[#1a365d] after:content-[''] after:absolute after:bottom-0 after:left-0 after:w-full after:h-1 after:bg-[#1a365d] after:rounded after:transition-transform after:duration-500"
                  : "text-gray-600 hover:text-[#1a365d]"
                  }`}
                onClick={() => setActiveTab("users")}
              >
                User Roles
              </button>
            </div>
          </div>
        </div>
        {activeTab === "roles" && (
          <div className="flex flex-col gap-6">
            <div className="flex flex-col md:flex-row items-center gap-4 w-full md:w-3/4">
              <input
                type="text"
                placeholder="Enter role..."
                value={role}
                onChange={(e) => setRole(e.target.value)}
                className="flex-1 p-2 border rounded-md focus:ring-2 focus:ring-[#1a365d]/100 focus:border-[#1a365d]/100 outline-none transition-all duration-200"
                disabled={actionsLoading?.addRole}
              />
              <button
                onClick={handleAddRole}
                disabled={actionsLoading?.addRole}
                className="px-4 py-2 bg-[#1a365d]/80 hover:bg-[#1a365d] text-[#f5f5f5] hover:text-white rounded-md transition-colors duration-200 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {actionsLoading?.addRole ? (
                  <span className="flex items-center gap-2">
                    <CircularProgress size={16} color="inherit" />
                    Creating...
                  </span>
                ) : (
                  "Create Role"
                )}
              </button>
            </div>
            <div className="flex flex-col md:flex-row gap-4">
              <div className="flex flex-col gap-4 flex-1">
                <div className="overflow-hidden border rounded-md p-4 shadow-inner bg-white w-full md:w-4/6">
                  <div className="mb-2">
                    <label className="block font-medium text-gray-700">
                      Roles
                    </label>
                    <div className="line mt-1"></div>
                  </div>
                  <div className="h-[48vh] overflow-y-auto custom-scrollbar">
                    {loading ? (
                      <RolesSkeleton />
                    ) : (
                      (roles || []).map((roleItem, index) => (
                        <div
                          key={index}
                          className="flex items-center justify-between p-2 hover:bg-gray-50 transition-colors duration-150 border-b last:border-none"
                        >
                          <div key={index} className="flex items-center gap-4">
                            <input
                              type="radio"
                              id={`role-${index}`}
                              name="roleSelection"
                              onChange={() => handleRoleSelect(roleItem)}
                              checked={role === roleItem}
                              className="text-[#1a365d] focus:ring-[#1a365d]/100"
                            />
                            <label
                              htmlFor={`role-${index}`}
                              className="cursor-pointer"
                            >
                              {roleItem}
                            </label>
                          </div>

                          <button
                            onClick={() => handleDelete(roleItem)}
                            disabled={actionsLoading?.deleteRole === roleItem}
                            className="text-red-500 hover:text-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {actionsLoading?.deleteRole === roleItem ? (
                              <CircularProgress size={16} color="inherit" />
                            ) : (
                              <i className="fa-solid fa-trash"></i>
                            )}
                          </button>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>
              <div className="flex-1">
                <div className="border rounded-md p-4 space-y-2 shadow-inner bg-white w-full md:w-5/6">
                  <div className="mb-2">
                    <label className="block font-medium text-gray-700">
                      Components
                    </label>
                    <div className="line mt-1"></div>
                  </div>
                  <div className="flex flex-wrap gap-2 mb-4">
                    {Object.keys(componentCategories).map((category) => (
                      <button
                        key={category}
                        onClick={() => handleCategorySelect(category)}
                        className={`px-3 py-1 rounded-md text-sm ${selectedCategory === category
                          ? "bg-[#1a365d]/80 text-[#f5f5f5]"
                          : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                          }`}
                      >
                        {category}
                      </button>
                    ))}
                  </div>
                  <div className="h-[44vh] overflow-y-auto custom-scrollbar border-b last:border-none">
                    {isComponentsLoading ? (
                      <ComponentsSkeleton />
                    ) : (
                      renderComponentsPanel()
                    )}
                  </div>
                </div>
              </div>
            </div>
            <div className=" flex justify-between">
              <div className="flex justify-between mt-4">
                <button
                  onClick={() => {
                    setRole("");
                    setComponents([]);
                    setSelectedCategory(null);
                    setSelectedSubCategory(null);
                  }}
                  className="text-[#f5f5f5] bg-[#1a365d]/80 hover:bg-[#1a365d] hover:text-white px-2 py-2 rounded"
                >
                  Clear Selection
                </button>
              </div>
              <div className="flex justify-between mt-4 mr-[7rem]">
                <button
                  onClick={handleSubmit}
                  disabled={actionsLoading?.submit || !role}
                  className="w-full px-6 py-2 bg-[#1a365d]/80 hover:bg-[#1a365d] text-[#f5f5f5] hover:text-white rounded-md transition-colors duration-200 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {actionsLoading?.submit ? (
                    <span className="flex items-center justify-center gap-2">
                      <CircularProgress size={16} color="inherit" />
                      Saving...
                    </span>
                  ) : (
                    "Submit"
                  )}
                </button>
              </div>
            </div>
          </div>
        )}
        {activeTab === "users" && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="text-left">
              <div className="flex flex-col gap-3 mb-4">
                <div className="flex flex-wrap items-center gap-2">
                  <div className="relative flex-1 min-w-[220px]">
                    <input
                      type="text"
                      placeholder="Search users..."
                      value={searchTerm}
                      onChange={(e) => handleSearch(e.target.value)}
                      onKeyDown={handleSearchKeyDown}
                      className="w-full p-2 pr-12 border rounded-md focus:ring-2 focus:ring-[#1a365d]/100 focus:border-[#1a365d]/100 outline-none transition-all duration-200"
                    />
                    <button
                      type="button"
                      onClick={handleSearchClick}
                      disabled={loading}
                      className="absolute right-1 top-1/2 -translate-y-1/2 p-2 text-gray-600 hover:text-[#1a365d] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                      title="Search"
                    >
                      <Search size={20} />
                    </button>
                  </div>
                </div>
                <div className="flex flex-wrap items-center justify-between gap-2 text-sm text-gray-600">
                  <div className="flex items-center gap-2">
                    <label className="text-sm text-gray-600">Pages</label>
                    <select
                      value={itemsPerPage}
                      onChange={(e) => handlePageSizeChange(e.target.value)}
                      className="w-28 p-2 border rounded-md focus:ring-2 focus:ring-[#1a365d]/100 focus:border-[#1a365d]/100 outline-none transition-all duration-200 bg-white"
                    >
                      <option value={10}>10</option>
                      <option value={20}>20</option>
                      <option value={50}>50</option>
                      <option value={100}>100</option>
                      <option value={200}>200</option>
                    </select>
                    <span>
                      Showing {filteredUsers.length > 0
                        ? `${(currentPage - 1) * itemsPerPage + 1}-${(currentPage - 1) * itemsPerPage + filteredUsers.length}`
                        : 0}
                    </span>
                  </div>
                  <div className="flex items-center gap-2">
                    <button
                      type="button"
                      onClick={() => handlePageChange(currentPage - 1)}
                      disabled={currentPage === 1 || loading}
                      className="px-3 py-1 bg-gray-100 rounded-md hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Previous
                    </button>
                    <button
                      type="button"
                      onClick={() => handlePageChange(currentPage + 1)}
                      disabled={filteredUsers.length < itemsPerPage || loading}
                      className="px-3 py-1 bg-gray-100 rounded-md hover:bg-gray-200 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      Next
                    </button>
                  </div>
                </div>
              </div>
              <div className="h-[60vh] overflow-y-auto border rounded-md shadow-inner bg-white custom-scrollbar">
                {loading ? (
                  <UsersSkeleton />
                ) : (
                  filteredUsers.map((user, index) => (
                    <div
                      key={index}
                      className={`p-3 cursor-pointer border-b-2 border-gray-200 transition-all duration-150
                        hover:bg-[#1a365db3] hover:text-[#f5f5f5] hover:border-b-0 hover:border-l-4 hover:border-[#1a365d]
                        ${selectedUser === user
                          ? "bg-[#1a365dcc] text-[#f5f5f5]"
                          : "bg-white text-[#00000099]"
                        }
                      `}
                      onClick={() => handleUserClick(user)}
                    >
                      {user}
                    </div>
                  ))
                )}
              </div>
            </div>
            <div>
              <div className="mb-4">
                <div className="flex justify-end h-10">
                  {selectedUser ? (
                    <button
                      onClick={handleAssignRole}
                      disabled={actionsLoading?.assignRole}
                      className="px-4 py-2 bg-[#1a365d]/80 hover:bg-[#1a365d] text-[#f5f5f5] hover:text-white rounded-md transition-colors duration-200 shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      {actionsLoading?.assignRole ? (
                        <span className="flex items-center gap-2">
                          <CircularProgress size={16} color="inherit" />
                          Assigning...
                        </span>
                      ) : (
                        "Assign Role"
                      )}
                    </button>
                  ) : (
                    <span className="px-4 py-2  rounded-md text-center w-full h-full flex items-center justify-center"></span>
                  )}
                </div>
              </div>
              <div className="h-[60vh] overflow-y-auto border rounded-md shadow-inner bg-white p-4 custom-scrollbar">
                {selectedUser ? (
                  <>
                    {userRolesLoading ? (
                      <UserRolesSkeleton />
                    ) : userRoles.length > 0 ? (
                      userRoles.map((userRole, index) => (
                        <div
                          key={index}
                          className="p-3 bg-gray-50 rounded-md flex justify-between items-center mb-2"
                        >
                          <li className="text-gray-500">{userRole}</li>
                          <button
                            onClick={() =>
                              removeRoleFromUser(selectedUser, userRole)
                            }
                            disabled={actionsLoading?.removeRole === userRole}
                            className="text-red-500 hover:text-red-700 disabled:opacity-50 disabled:cursor-not-allowed"
                          >
                            {actionsLoading?.removeRole === userRole ? (
                              <CircularProgress size={16} color="inherit" />
                            ) : (
                              <i className="fa-solid fa-trash"></i>
                            )}
                          </button>
                        </div>
                      ))
                    ) : (
                      <p className="text-gray-500 text-center mt-4">
                        No roles found
                      </p>
                    )}
                  </>
                ) : (
                  <p className="text-gray-500 text-center mt-4">
                    Select a user to view and manage roles
                  </p>
                )}
              </div>
            </div>
          </div>
        )}
        <Dialog
          open={showRoleDialog}
          onClose={() => setShowRoleDialog(false)}
          fullWidth
          maxWidth="xs"
        >
          <DialogTitle sx={{ color: "#1a365d]", fontSize: "18px" }}>
            Add Role for {selectedUser}
          </DialogTitle>
          <DialogContent>
            <FormControl fullWidth margin="normal">
              <InputLabel htmlFor="role-select" sx={{ color: "#1a365d" }}>
                Select Role
              </InputLabel>
              <Select
                id="role-select"
                value={selectedRole}
                label="Select Role"
                onChange={(e) => setSelectedRole(e.target.value)}
                disabled={actionsLoading?.assignRole}
                sx={{
                  backgroundColor: "#f5f5f5",
                  color: "#1a365d",
                  borderRadius: "0.375rem",

                  "& .MuiSelect-icon": { color: "#f5f5f5" },
                }}
                MenuProps={{
                  PaperProps: {
                    sx: {
                      backgroundColor: "#f5f5f5",
                      color: "#1a365d",
                    },
                  },
                }}
              >
                <MenuItem value="selectrole"></MenuItem>
                {(roles || []).map((role, index) => (
                  <MenuItem
                    key={index}
                    value={role}
                    sx={{
                      backgroundColor: "#f5f5f5",
                      color: "#1a365d",
                      "&.Mui-selected": {
                        backgroundColor: "#f5f5f5",
                        color: "#1a365dcc",
                      },
                      "&:hover": {
                        backgroundColor: "#1a365dcc",
                        color: "#f5f5f5",
                      },
                    }}
                  >
                    {role}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </DialogContent>
          <DialogActions>
            <Button
              onClick={() => {
                setShowRoleDialog(false);
                setSelectedRole("");
              }}
              disabled={actionsLoading?.assignRole}
              sx={{
                backgroundColor: "#1a365dcc",
                color: "#f5f5f5",
                "&:hover": { backgroundColor: "#1a365d", color: "#fff" },
                borderRadius: "0.375rem",
                p: 1,
                boxShadow: 1,
                opacity: actionsLoading?.assignRole ? 0.5 : 1,
                cursor: actionsLoading?.assignRole ? "not-allowed" : "pointer",
              }}
            >
              Cancel
            </Button>

            <Button
              onClick={handleRoleAssignment}
              disabled={actionsLoading?.assignRole}
              startIcon={
                actionsLoading?.assignRole ? (
                  <CircularProgress sx={{ color: "#f5f5f5" }} size={20} />
                ) : null
              }
              sx={{
                backgroundColor: "#1a365dcc",
                color: actionsLoading?.assignRole ? "#fff" : "#f5f5f5",
                "&:hover": { backgroundColor: "#1a365d", color: "#fff" },
                borderRadius: "0.375rem",
                p: 1,
                boxShadow: 1,
                opacity: actionsLoading?.assignRole ? 0.5 : 1,
                cursor: actionsLoading?.assignRole ? "not-allowed" : "pointer",
              }}
            >
              {actionsLoading?.assignRole ? "Adding..." : "Add Role"}
            </Button>
          </DialogActions>
        </Dialog>
      </div>
    </div>
  );
};

export default UserManagement;
